import {sum,group,recordDate,makeExamples,measure,summarize,quantile,validateImport,days} from './analysis.js';
import {createMap} from './map.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('en-US'),short=n=>n>=1000?(n/1000).toFixed(n>=10000?0:1)+'k':fmt(n),displayDate=s=>s?new Date(s+'T00:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}):'Not verified';
const stateNames={CA:'California',NY:'New York',WA:'Washington'},colors=['#e98068','#5b9a90','#cfb77c','#9baab5'];
const state={page:'overview',mode:'official',baseline:'posting',outlet:'national',chart:'bar',mapMode:'events',tablePage:0,sort:'recent'};
let official=[],examples=makeExamples(),imported=[],metadata={},map=null,renderToken=0;
const rows=()=>state.mode==='example'?examples:state.mode==='imported'?imported:official;
function filtered(){const quality=$('#quality').value;return rows().filter(e=>(!$('#state').value||e.state===$('#state').value)&&(!$('#industry').value||e.industry===$('#industry').value)&&(!quality||(quality==='posting'&&e.postedDate)||(quality==='receipt'&&e.receivedDate)||(quality==='interval'&&e.firstSeenDate&&e.lastAbsentDate)||(quality==='unverified'&&!e.postedDate))&&(!$('#company').value||e.company.toLowerCase().includes($('#company').value.toLowerCase()))&&(!$('#from').value||recordDate(e)>=$('#from').value)&&(!$('#to').value||recordDate(e)<=$('#to').value));}
const mark=(v,fallback='—')=>v==null?fallback:Number.isInteger(v)?fmt(v):v.toFixed(1);
const badge=e=>{const m=measure(e,state.baseline,state.outlet);return `<span class="status ${m.status==='matched'?'matched':m.status==='none'?'none':''}">${m.status==='matched'?'Report matched':m.status==='none'?'No coverage found':'Not yet reviewed'}</span>`};
const metric=(label,value,sub,accent=false,icon='↗')=>`<article class="metric ${accent?'accent':''}"><div class="label">${label}</div><span class="mini">${icon}</span><div class="num">${value}</div><div class="sub">${sub}</div></article>`;
const card=(title,desc,content,tag='')=>`<article class="card"><div class="card-head"><div><h2>${title}</h2><p class="description">${desc}</p></div>${tag?`<span class="tag">${tag}</span>`:''}</div>${content}</article>`;
const empty=(title='Reviewed evidence comes first',msg='These records have not completed news matching. No latency or coverage finding is inferred.')=>`<div class="empty"><strong>${title}</strong><span>${msg}</span>${state.mode!=='example'?'<button data-example>Explore the labeled example study ↗</button>':''}</div>`;
function svgStart(w=560,h=230,label='Chart'){return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}">`}
function svgGrid(yMax,w=560,h=230,min=0){let out='';for(let i=0;i<=4;i++){const y=20+i*(h-60)/4;out+=`<line class="grid" x1="45" x2="${w-15}" y1="${y}" y2="${y}"/><text x="35" y="${y+4}" text-anchor="end">${short(yMax-(yMax-min)*i/4)}</text>`}return out}
function trendChart(data){const groups=group(data.map(e=>({...e,month:recordDate(e).slice(0,7)||'Unknown'})),'month').sort((a,b)=>a.name.localeCompare(b.name));if(!groups.length)return empty('No records in this selection','Try resetting a filter.');const max=Math.max(...groups.map(g=>sum(g.rows)),1)*1.15,w=560,h=230,step=500/groups.length,py=n=>190-170*n/max;let svg=svgStart(w,h,'Affected workers by record month')+svgGrid(max,w,h);const points=[];groups.forEach((g,i)=>{const x=45+(i+.5)*step,y=py(sum(g.rows)),label=g.name==='Unknown'?'Unknown':new Date(g.name+'-01T00:00:00Z').toLocaleDateString('en-US',{month:'short',year:'2-digit',timeZone:'UTC'});points.push([x,y]);if(state.chart==='bar')svg+=`<rect x="${x-step*.29}" y="${y}" width="${step*.58}" height="${190-y}" rx="3" fill="#e98068" opacity=".85"><title>${label}: ${fmt(sum(g.rows))} workers; ${g.rows.length} records</title></rect>`;if(groups.length<=12||i%Math.ceil(groups.length/10)===0)svg+=`<text x="${x}" y="216" text-anchor="middle">${esc(label)}</text>`});if(state.chart==='line'){svg+=`<path d="M${points.map(p=>p.join(',')).join(' L')}" fill="none" stroke="#5b9a90" stroke-width="2.5"/>`;points.forEach(([x,y],i)=>svg+=`<circle cx="${x}" cy="${y}" r="4" fill="#5b9a90"><title>${groups[i].name}: ${fmt(sum(groups[i].rows))} workers</title></circle>`)}return `<div class="chart">${svg}</svg></div><div class="chart-legend">Record month uses available listed posting, receipt, processed, or notice date. Dates are not pooled for latency.</div>`}
function industryChart(data){const gs=group(data,'industry').sort((a,b)=>sum(b.rows)-sum(a.rows)).slice(0,6);if(!gs.length)return empty('No records in this selection','Try resetting a filter.');const max=Math.max(...gs.map(g=>sum(g.rows)),1);return `<div class="side-body">${gs.map((g,i)=>`<button class="group-button" data-industry="${esc(g.name)}"><div class="state-item"><div class="state-top"><span>${esc(g.name.length>42?g.name.slice(0,40)+'…':g.name)}</span><strong>${short(sum(g.rows))}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${sum(g.rows)/max*100}%;background:${colors[i%4]}"></div></div><div class="state-sub">${fmt(g.rows.length)} records · ${esc(g.name)}</div></div></button>`).join('')}</div>`}
function table(data,limit=7){let sorted=[...data].sort((a,b)=>state.sort==='workers'?b.workers-a.workers:recordDate(b).localeCompare(recordDate(a)));const start=state.tablePage*limit,shown=sorted.slice(start,start+limit);return `<div class="table-scroll"><table><thead><tr><th>EMPLOYER / LOCATION</th><th>STATE</th><th>AFFECTED WORKERS</th><th>RECORD DATE</th><th>COVERAGE REVIEW</th><th></th></tr></thead><tbody>${shown.map(e=>`<tr><td><button data-event="${esc(e.id)}">${esc(e.company)}</button><span class="company-sub">${esc(e.city||e.county||'Location not specified')}</span></td><td>${esc(e.state)}</td><td>${fmt(e.workers)}</td><td>${displayDate(recordDate(e))}</td><td>${badge(e)}</td><td><button data-event="${esc(e.id)}" aria-label="Inspect ${esc(e.company)}">↗</button></td></tr>`).join('')||'<tr><td colspan="6">No matching records. Try another filter.</td></tr>'}</tbody></table></div><div class="table-foot"><span>${sorted.length?start+1:0}–${Math.min(start+limit,sorted.length)} of ${fmt(sorted.length)} records</span><div><button id="prev" ${start===0?'disabled':''}>← Previous</button><button id="next" ${start+limit>=sorted.length?'disabled':''}>Next →</button></div></div>`}
function overview(data){const m=summarize(data,'posting',state.outlet),states=['CA','NY','WA'].map(s=>({s,rows:data.filter(e=>e.state===s)})),max=Math.max(...states.map(g=>sum(g.rows)),1);return `<section class="metrics">${metric('Source records in this selection',fmt(data.length),'Source records · amendments may be present')}${metric('Workers in these records',fmt(sum(data)),'Reported planned reductions',false,'◌')}${metric('States in focus',new Set(data.map(e=>e.state)).size,'California · New York · Washington',false,'⌖')}${metric('Quiet Cut Index · 30 days',m.qci==null?'—':m.qci.toFixed(1)+'%',m.qci==null?'Awaiting completed evidence reviews':`${m.none} / ${m.eligible} eligible · ${m.excluded} excluded`,true,'◷')}</section>
<section class="grid-main"><article class="card map-card"><div class="card-head"><div><h2>A geography of workforce change</h2><p class="description">Explore the map. Zoom in to reveal local detail.</p></div><span class="tag" id="map-engine">LOADING WASM</span></div><div class="map-container"><canvas id="map" tabindex="0" aria-label="Interactive US WARN map. Drag to pan; use plus and minus to zoom; arrow keys to pan. Select an event circle to view evidence."></canvas><div class="map-layer-control"><button data-map-mode="events" class="${state.mapMode==='events'?'active':''}">Event circles</button><button data-map-mode="regions" class="${state.mapMode==='regions'?'active':''}">State heatmap</button></div><div class="map-state-shortcuts"><button data-fit="US">US</button><button data-fit="CA">CA</button><button data-fit="WA">WA</button><button data-fit="NY">NY</button></div><div class="map-controls"><button id="zoom-in" aria-label="Zoom in">+</button><button id="zoom-out" aria-label="Zoom out">−</button><button data-fit="US" aria-label="Reset map">↺</button></div><div id="map-error" hidden class="map-error"></div></div><div class="map-foot"><span class="legend" id="map-legend">${state.mapMode==='events'?'<span><i></i> Circle size = reported workers (capped)</span>':'<span class="heat-scale"></span><span>Low → high state sample totals</span>'}<span>Gray = outside study</span></span><span id="map-stats">Preparing visible tiles…</span></div></article>
${card('Three states. Different signals.','Workers in the selected source records',`<div class="side-body">${states.map(({s,rows:r},i)=>`<button class="group-button" data-state="${s}"><div class="state-item"><div class="state-top"><span>${stateNames[s]} <span style="color:#a4afa6;font-size:9px">${s}</span></span><strong>${short(sum(r))}</strong></div><div class="state-sub">${fmt(r.length)} records <span style="float:right">Explore ↗</span></div><div class="bar-track"><div class="bar-fill" style="width:${sum(r)/max*100}%;background:${colors[i]}"></div></div></div></button>`).join('')}<div class="callout"><strong>Context matters.</strong> This is a collected sample, not a ranking of state labor markets. Different collection windows limit comparisons.</div></div>`,'COHORT')}</section>
<section class="grid-two"><article class="card"><div class="card-head"><div><h2>Workforce reductions over time</h2><p class="description">Reported workers · by available record month</p></div><div class="toggle-group"><button data-chart="bar" class="${state.chart==='bar'?'active':''}">Bars</button><button data-chart="line" class="${state.chart==='line'?'active':''}">Line</button></div></div>${trendChart(data)}</article>${card('Industry composition','Reported workers · top six source classifications',industryChart(data))}</section><div class="section-heading"><div><h2>Behind every point, a public record</h2><p>Recent notices, with evidence one click away.</p></div><button class="text-button" data-page="employers">Explore all employers ↗</button></div><article class="card">${table(data)}</article>`}
function scatter(data){const matched=summarize(data,state.baseline,state.outlet).matched;if(!matched.length)return empty();const maxX=Math.max(...matched.map(m=>m.event.workers),1)*1.12,minY=-30,maxY=30,w=560,h=255,x=n=>50+n/maxX*490,y=n=>205-(n-minY)/(maxY-minY)*175;let svg=svgStart(w,h,'Worker count and reporting delay scatterplot');for(const v of [-30,-15,0,15,30])svg+=`<line class="${v===0?'zero':'grid'}" x1="50" x2="540" y1="${y(v)}" y2="${y(v)}"/><text x="40" y="${y(v)+4}" text-anchor="end">${v}</text>`;for(let i=0;i<5;i++)svg+=`<text x="${50+i*122.5}" y="226" text-anchor="middle">${short(maxX*i/4)}</text>`;matched.forEach(m=>{if(m.range)svg+=`<line x1="${x(m.event.workers)}" x2="${x(m.event.workers)}" y1="${y(m.range[0])}" y2="${y(m.range[1])}" stroke="#96b4a1"/>`;svg+=`<circle data-event="${esc(m.event.id)}" tabindex="0" role="button" aria-label="${esc(m.event.company)}: ${m.delay} days" cx="${x(m.event.workers)}" cy="${y(m.delay)}" r="5" fill="${colors[['CA','NY','WA'].indexOf(m.event.state)]}" opacity=".8"><title>${esc(m.event.company)} · ${m.event.workers} workers · ${m.delay} days${m.range?' (range '+m.range.join(' to ')+')':''}</title></circle>`});return `<div class="chart">${svg}<text x="295" y="249" text-anchor="middle">Affected workers</text><text x="50" y="14">Delay in days</text></svg></div><div class="chart-legend legend"><span><i></i> CA</span><span><i class="teal"></i> NY</span><span>● WA</span><span>Negative delay = reporting before baseline</span></div>`}
function boxplot(data){const gs=group(data,'industry').map(g=>({...g,values:summarize(g.rows,state.baseline,state.outlet).matched.map(m=>m.delay)})).filter(g=>g.values.length).slice(0,6);if(!gs.length)return empty();const h=Math.max(225,gs.length*43+65),x=n=>145+(n+30)/60*385;let svg=svgStart(560,h,'Reporting delay distribution by industry');for(let v=-30;v<=30;v+=15)svg+=`<line x1="${x(v)}" x2="${x(v)}" y1="15" y2="${h-40}" class="${v===0?'zero':'grid'}"/><text x="${x(v)}" y="${h-22}" text-anchor="middle">${v}</text>`;gs.forEach((g,i)=>{const y=35+i*43,vals=g.values;svg+=`<text x="5" y="${y-2}">${esc(g.name.slice(0,20))}</text><text x="5" y="${y+12}">n = ${vals.length}</text>`;if(vals.length>=5){const a=quantile(vals,.25),b=quantile(vals,.75),med=quantile(vals,.5);svg+=`<line x1="${x(Math.min(...vals))}" x2="${x(Math.max(...vals))}" y1="${y}" y2="${y}" stroke="#76a191"/><rect x="${x(a)}" y="${y-10}" width="${Math.max(1,x(b)-x(a))}" height="20" fill="#dcece3" stroke="#76a191"/><line x1="${x(med)}" x2="${x(med)}" y1="${y-10}" y2="${y+10}" stroke="#376f59" stroke-width="2"/>`;}vals.forEach((v,j)=>svg+=`<circle cx="${x(v)}" cy="${y+(j%3-1)*4}" r="2.5" fill="#e98068" opacity=".65"><title>${v} days</title></circle>`)});return `<div class="chart">${svg}</svg></div><div class="chart-legend">Boxes = 25th–75th percentile; line = median; whiskers = min/max. Fewer than five matches: dots only.</div>`}
function qciChart(data){const gs=group(data,'industry');if(!gs.some(g=>summarize(g.rows,state.baseline,state.outlet).eligible))return empty('No eligible denominator yet','Incomplete searches and unverified baselines are excluded, never counted as silence.');return `<div class="side-body">${gs.map(g=>{const m=summarize(g.rows,state.baseline,state.outlet);return `<div class="qci-row"><span>${esc(g.name)}</span><div><div class="bar-track"><div class="bar-fill" style="width:${m.qci||0}%"></div></div><small>${m.none} / ${m.eligible} eligible · ${m.excluded} excluded</small></div><strong>${m.qci==null?'Not eligible':m.qci.toFixed(1)+'%'}</strong></div>`}).join('')}</div><p class="muted-note">No matching report found in the selected outlet set from −30 to +30 days. This is not a measure of all media coverage.</p>`}
function timeline(data){const repeats=group(data,'company').filter(g=>g.rows.length>1).sort((a,b)=>b.rows.length-a.rows.length).slice(0,5);if(!repeats.length)return empty('No repeated employers in this selection','Repeated records require review to distinguish new events from amendments.');const dates=repeats.flatMap(g=>g.rows.flatMap(e=>[e.postedDate,e.receivedDate,e.noticeDate,e.effectiveDate,e.announcementDate,measure(e,state.baseline,state.outlet).news?.date])).filter(Boolean).sort(),min=Date.parse(dates[0]),max=Date.parse(dates.at(-1)),x=d=>170+(Date.parse(d)-min)/(max-min||1)*520,h=70+repeats.length*47;let svg=svgStart(730,h,'Repeated employer event timelines');repeats.forEach((g,i)=>{const y=39+i*47;svg+=`<text x="8" y="${y+4}">${esc(g.name.slice(0,23))}</text><line x1="170" x2="700" y1="${y}" y2="${y}" class="grid"/>`;g.rows.forEach(e=>{const n=measure(e,state.baseline,state.outlet).news;for(const [date,color,symbol] of [[e.postedDate||e.receivedDate||e.noticeDate,'#5b9a90','notice'],[e.announcementDate,'#cfb77c','announcement'],[n?.date,'#e98068','news'],[e.effectiveDate,'#9aa9b4','effective']])if(date){svg+=`<g data-event="${esc(e.id)}" tabindex="0" role="button" aria-label="${esc(e.company)} ${symbol} ${date}">`;svg+=symbol==='effective'?`<path d="M${x(date)} ${y-5} l5 5 l-5 5 l-5 -5 Z" fill="${color}"/>`:symbol==='news'?`<rect x="${x(date)-4}" y="${y-4}" width="8" height="8" fill="${color}"/>`:`<circle cx="${x(date)}" cy="${y}" r="${symbol==='announcement'?3:4}" fill="${color}"/>`;svg+=`<title>${esc(e.company)} · ${symbol} · ${date}</title></g>`}})});svg+=`<text x="170" y="${h-12}">${displayDate(dates[0])}</text><text x="700" y="${h-12}" text-anchor="end">${displayDate(dates.at(-1))}</text>`;return `<div class="chart timeline-svg">${svg}</svg></div><p class="muted-note">● Notice / receipt (see event details) · ● company announcement · ■ verified news · ◆ planned effective date. Repeated records may include amendments; review before counting distinct events.</p>`}
function latency(data){const m=summarize(data,state.baseline,state.outlet);return `<div class="analysis-controls"><label>Baseline<select id="baseline"><option value="posting" ${state.baseline==='posting'?'selected':''}>Verified public posting</option><option value="receipt" ${state.baseline==='receipt'?'selected':''}>Agency receipt · separate measure</option><option value="interval" ${state.baseline==='interval'?'selected':''}>Prospective first-seen interval</option></select></label><label>Outlet set<select id="outlet"><option value="national" ${state.outlet==='national'?'selected':''}>National outlets</option><option value="combined" ${state.outlet==='combined'?'selected':''}>National + regional outlets</option></select></label><p>${state.baseline==='receipt'?'Receipt-to-news is a separate measure. Its no-match rate is not the proposal’s public-visibility QCI30.':'Only verified baselines qualify. Incomplete or failed searches remain outside the QCI denominator.'}</p></div><section class="metrics">${metric('Matched reports',fmt(m.matched.length),'Within the specified ±30-day window')}${metric(state.baseline==='interval'?'Median first-seen-to-news':'Median reporting delay',m.median==null?'—':mark(m.median)+'d','Matched events only · day precision')}${metric('Eligible completed searches',fmt(m.eligible),`${m.excluded} excluded from denominator`)}${metric(state.baseline==='receipt'?'Receipt-based no-match rate':'Quiet Cut Index · QCI30',m.qci==null?'—':m.qci.toFixed(1)+'%',`${m.none} with no matching report found`,true)}</section><section class="grid-two">${card('Does event size affect visibility?','Affected workers × reporting delay',scatter(data),'RQ 01 / 02')}${card('A distribution, not just an average','Reporting delay by industry · matched events only',boxplot(data),'RQ 01')}${card(state.baseline==='receipt'?'Receipt-based search outcomes':'The Quiet Cut Index','Observed no-coverage share by industry',qciChart(data),'RQ 03')}${card('How complete is the evidence?','Search status for the current baseline and outlet set',statusChart(data),'AUDIT')}</section><div class="section-heading"><h2>Follow recurring employer records</h2></div>${card('From notice to reporting','Separate notice, announcement, news, and planned effective dates',timeline(data),'RQ 04')}`}
function statusChart(data){const m=summarize(data,state.baseline,state.outlet),list=[['Complete · report matched',m.eligible-m.none,'#5b9a90'],['Complete · no report found',m.none,'#e98068'],['Excluded / incomplete',m.excluded,'#c6cec8']];return `<div class="side-body">${list.map(([name,n,c])=>`<div class="state-item"><div class="state-top"><span>${name}</span><strong>${fmt(n)}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${data.length?n/data.length*100:0}%;background:${c}"></div></div></div>`).join('')}</div><p class="muted-note">A matched article can appear before full follow-up ends. Coverage-rate calculations still require the full search window.</p>`}
function employers(data){return `<section class="metrics">${metric('Employers',fmt(new Set(data.map(e=>e.company)).size),'Names as recorded by the source')}${metric('Repeated employer names',fmt(group(data,'company').filter(g=>g.rows.length>1).length),'May include amendments or multiple sites')}${metric('Largest notice',data.length?fmt(Math.max(...data.map(e=>e.workers))):'—','Reported workers in a single source row')}${metric('Source-linked records',fmt(data.filter(e=>e.sourceUrl).length),'Inspect any record to see provenance',true)}</section><div class="section-heading"><h2>Employer records</h2><label style="font-size:10px">Sort <select id="sort"><option value="recent" ${state.sort==='recent'?'selected':''}>Most recent record</option><option value="workers" ${state.sort==='workers'?'selected':''}>Most affected workers</option></select></label></div><article class="card">${table(data,15)}</article><section class="grid-two">${card('Repeated employer histories','Notices and planned effective dates',timeline(data))}${card('Industry composition','Source industry labels retained; unknowns kept visible',industryChart(data))}</section><section class="feature-boxes"><article class="card feature-box"><h2>AI attribution requires evidence</h2><p>${fmt(data.length)} records have no reviewed AI-causation classification. An employer’s industry does not establish whether AI caused a reduction. No AI/non-AI split is inferred.</p><span class="tag">NOT CODED</span></article><article class="card feature-box"><h2>Salary is not part of this sample</h2><p>The proposal’s salary screenshot uses a different dataset. These WARN sources do not provide comparable median salaries; adding them would require a documented wage-data join.</p><span class="tag">SOURCE DATA UNAVAILABLE</span></article></section>`}
const sources=[['California EDD','Official WARN reports and current XLSX. Date fields are retained as labeled, including processed dates.','https://edd.ca.gov/en/jobs_and_training/layoff_services_warn/'],['New York Department of Labor','WARN dashboard and notice documents. Listed posting dates are not assumed to be original postings.','https://dol.ny.gov/warn-notices'],['Washington ESD','Official layoff and closure database. Receipt dates are not public posting dates.','https://esd.wa.gov/employer-requirements/layoffs-and-employee-notifications/worker-adjustment-and-retraining-notification-warn-layoff-and-closure-database'],['GDELT DOC 2.0','Candidate article discovery. Publisher dates and event matches still need verification.','https://blog.gdeltproject.org/gdelt-doc-2-0-api-debuts/'],['U.S. Department of Labor','Federal WARN overview, coverage, and notice requirements.','https://www.dol.gov/agencies/eta/layoffs/warn'],['U.S. Census Bureau','NAICS classification; Information (51) is only a limited technology proxy.','https://www.census.gov/naics/'],['Map data & rendering','US Atlas boundary data; Skia CanvasKit performs drawing in WebAssembly.','https://github.com/topojson/us-atlas']];
function method(data){return `<section class="method-grid"><article class="card"><div class="card-head"><div><h2>Designed for a defensible answer</h2><p class="description">What this dashboard measures — and what it cannot claim</p></div><span class="tag">METHOD / V1</span></div><div class="prose"><h3>01 / A public record is the beginning</h3><p>The study follows employer-site WARN events in California, New York, and Washington. The official dataset is a preserved source sample, not a completed reviewed cohort. California includes 368 rows from July 1–October 14, 2026; New York includes 208 impacted-site rows from the dashboard’s default current export; Washington includes only 15 rows from the first database page. Source rows may include amendments or multiple sites; totals describe the records, and are not deduplicated estimates of jobs lost.</p><h3>02 / Keep the clocks separate</h3><p>Posting-to-news delay is the earliest verified matching publication date minus a verified original public posting date. Receipt, processed, notice, and planned effective dates stay separate. A displayed posting date whose amendment status is unknown does not qualify as a verified original posting.</p><p>Prospective observation uses the interval between the last successful snapshot without the notice and the first snapshot containing it. Delay is shown as a range. All current date calculations use day precision; news observation and update timestamps are not publication dates.</p><h3>03 / Search a fixed window</h3><p>Search from 30 days before to 30 days after each baseline. The national outlet set is Reuters, AP, The New York Times, The Wall Street Journal, CNBC, CNN, and BBC. The regional comparison list must be frozen and documented before a reviewed study begins. The example toggle illustrates this comparison using fictional records.</p><div class="formula">QCI30 = 100 × no matching report found / eligible completed searches</div><p>Failed, unresolved, or incomplete searches and unverified baselines are excluded. A no-match result means no observed coverage within the defined sources and window, never proof that no coverage exists. Receipt-based no-match rates are labeled separately.</p><h3>04 / Inspect the evidence</h3><p>Every official record links to its agency source. Independent review must resolve aliases, subsidiaries, site context, amendments, and publication dates before real latency results are reported. Negative delays mean news preceded the baseline.</p><h3>05 / Scope and data quality</h3><p>WARN is not a census of layoffs. The map shows the US for geographic context, but only the three-state sample has data; other states are not zero. Locations are approximate city or county centroids, not workplace coordinates. Missing coordinates remain in tables and totals.</p><p>Salary and AI-attribution figures in the proposal are design references, not supplied study data. Those measures are explicitly unavailable. The current official sample is not restricted to the proposed Information, Finance, and Manufacturing cohort; use source industry filters and review classifications before constructing that cohort.</p><h3>06 / A map with bounded detail</h3><p>Skia CanvasKit draws the map through WebAssembly. Only viewport tiles at the active zoom are requested; county detail arrives when zooming in. A 32-tile cache, four-request limit, canceled obsolete requests, explicit native-object cleanup, and capped display resolution constrain map resource use. CanvasKit itself starts with a measured 128 MiB WASM heap before browser and GPU allocations; total RAM is not fixed. The status strip reports active tiles and cached geometry bytes; those bytes are not total browser RAM.</p><p><a href="https://skia.org/docs/user/modules/quickstart/" target="_blank" rel="noopener">CanvasKit documentation ↗</a> · <a href="vendor/MAP-ARCHITECTURE.md" target="_blank">Map implementation notes ↗</a></p></div></article><div><article class="card"><div class="card-head"><div><h2>Go straight to the source</h2><p class="description">Primary records and research documentation</p></div></div><div class="source-list">${sources.map(([name,desc,url])=>`<a class="source-item" href="${url}" target="_blank" rel="noopener"><strong>${name} ↗</strong><p>${desc}</p><span>${new URL(url).hostname}</span></a>`).join('')}</div></article><article class="card" style="margin-top:18px"><div class="card-head"><div><h2>Bring a reviewed event table</h2><p class="description">Local to this browser session · JSON format</p></div></div><div class="prose"><label class="upload">Import a source-linked, reviewed dataset. This does not overwrite the official sample.<input type="file" id="import" accept=".json,application/json"></label><div class="import-error" id="import-error"></div><button class="action-link" id="schema">Download event template</button><button class="action-link" id="export-json">Download current JSON</button><p>Keep an external copy: imported data is not persisted or uploaded. The template explains required evidence and search-completion fields.</p></div></article><article class="card" style="margin-top:18px"><div class="card-head"><div><h2>Collection snapshot</h2><p class="description">Reproducibility and coverage</p></div></div><div class="prose" id="metadata-details">${metadataText()}</div></article></div></section>`}
function metadataText(){return `<p>${fmt(official.length)} official source rows. Collected for this application on October 17, 2026.</p><p>${['CA','NY','WA'].map(s=>`${stateNames[s]}: ${fmt(official.filter(e=>e.state===s).length)} rows`).join('<br>')}</p><p>No official news matches have been reviewed. Official records therefore do not yet yield a reporting-delay distribution or QCI30 finding.</p><a href="data/events.json" target="_blank">Open full snapshot and metadata ↗</a>`}
function refreshIndustries(){const prev=$('#industry').value;$('#industry').innerHTML='<option value="">All industries</option>'+[...new Set(rows().map(e=>e.industry||'Unknown'))].sort().map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');if([...$('#industry').options].some(o=>o.value===prev))$('#industry').value=prev}
async function render(){const token=++renderToken;map?.destroy();map=null;const data=filtered(),titles={overview:['Every notice has a story.','Explore workforce reductions. Trace when the news catches up.'],latency:['From public notice to public attention.','Compare reporting delays without losing the uncertainty.'],employers:['The records behind the reductions.','Search employers, follow their histories, and inspect the evidence.'],method:['Good questions need clear evidence.','Sources, definitions, and the limits of what we can know.']};$('#page-title').textContent=titles[state.page][0];$('#page-subtitle').textContent=titles[state.page][1];$('#crumb').textContent={overview:'Overview',latency:'Reporting latency',employers:'Employer explorer',method:'Sources & method'}[state.page];document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));$('#mode-note').className='notice'+(state.mode==='example'?' example':'');$('#mode-note').textContent=state.mode==='example'?'ILLUSTRATIVE STUDY · All 72 events, employers, dates, and reporting outcomes are fictional. Use this mode to explore the method, not as a finding.':state.mode==='imported'?'IMPORTED DATA · Supplied for this browser session. Source and review flags are supplied by the importer; verify them before interpreting results.':'OFFICIAL SOURCE SNAPSHOT · News matching is not yet reviewed. These records show planned reductions; missing coverage has not been established.';$('#data-date').textContent=state.mode==='example'?'Fictional study · Jan–Aug 2026':state.mode==='imported'?'Session-only reviewed dataset':'Source snapshot · 17 Oct 2026';$('#view').innerHTML=({overview,latency,employers,method}[state.page])(data);bindView();if(state.page==='overview'){try{const instance=await createMap($('#map'),{onSelect:showEvidence,onStats:s=>{if(token!==renderToken)return;$('#map-engine').textContent='WEBASSEMBLY · SKIA';$('#map-stats').textContent=`${s.renderedTiles??s.visibleTiles} visible · ${s.cachedTiles}/32 cached · ${Math.round(s.tileBytes/1024)} KB geometry${s.countyDetail?' · county detail':''}`},onError:msg=>{if(token!==renderToken)return;$('#map-error').hidden=false;$('#map-error').textContent=msg;$('#map-engine').textContent='MAP UNAVAILABLE'}});if(token!==renderToken){instance.destroy();return}map=instance;map.setEvents(data);map.setMode(state.mapMode);if($('#state').value)map.fit($('#state').value);}catch(e){if(token===renderToken){$('#map-error').hidden=false;$('#map-error').textContent='The map could not initialize. Tables and charts remain available. '+e.message;$('#map-engine').textContent='MAP UNAVAILABLE'}}}}
function bindView(){document.querySelectorAll('#view [data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{$('#dataset').value='example';changeMode()});document.querySelectorAll('#view [data-event]').forEach(b=>{b.onclick=()=>showEvidence(b.dataset.event);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showEvidence(b.dataset.event)}}});document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{$('#state').value=b.dataset.state;state.tablePage=0;render()});document.querySelectorAll('[data-industry]').forEach(b=>b.onclick=()=>{$('#industry').value=b.dataset.industry;state.tablePage=0;render()});document.querySelectorAll('[data-fit]').forEach(b=>b.onclick=()=>map?.fit(b.dataset.fit));document.querySelectorAll('[data-map-mode]').forEach(b=>b.onclick=()=>{state.mapMode=b.dataset.mapMode;map?.setMode(state.mapMode);document.querySelectorAll('[data-map-mode]').forEach(el=>el.classList.toggle('active',el.dataset.mapMode===state.mapMode));$('#map-legend').innerHTML=state.mapMode==='events'?'<span><i></i> Circle size = reported workers (capped)</span><span>Gray = outside study</span>':'<span class="heat-scale"></span><span>Low → high state sample totals</span><span>Gray = outside study</span>'});document.querySelectorAll('[data-chart]').forEach(b=>b.onclick=()=>{state.chart=b.dataset.chart;render()});if($('#zoom-in'))$('#zoom-in').onclick=()=>map?.zoomBy(1);if($('#zoom-out'))$('#zoom-out').onclick=()=>map?.zoomBy(-1);if($('#prev'))$('#prev').onclick=()=>{state.tablePage--;render()};if($('#next'))$('#next').onclick=()=>{state.tablePage++;render()};for(const key of ['baseline','outlet','sort'])if($('#'+key))$('#'+key).onchange=e=>{state[key]=e.target.value;state.tablePage=0;render()};if($('#import'))$('#import').onchange=importData;if($('#schema'))$('#schema').onclick=downloadSchema;if($('#export-json'))$('#export-json').onclick=()=>download(JSON.stringify({metadata:{mode:state.mode,exportedAt:new Date().toISOString()},events:filtered()},null,2),'quiet-cuts-'+state.mode+'.json','application/json')}
function showEvidence(id){const e=rows().find(e=>e.id===id);if(!e)return;const m=measure(e,state.baseline,state.outlet);map?.select?.(id);const dl=[['Source notice date',e.noticeDate],['Agency receipt date',e.receivedDate],['Agency processed date',e.processedDate],['Listed posting (original unverified)',e.listedPostedDate],['Verified public posting',e.postedDate],['Last absent snapshot',e.lastAbsentDate],['First seen snapshot',e.firstSeenDate],['Company announcement',e.announcementDate],['Earliest verified matching news',m.news?.date],['Planned effective date',e.effectiveDate]].filter(([,d])=>d);$('#evidence-content').innerHTML=`<h2 class="drawer-title">${esc(e.company)}</h2><p class="drawer-location">${esc(e.city||e.county||'Location unspecified')} · ${stateNames[e.state]}</p>${badge(e)}<div class="detail-grid"><div><label>REPORTED WORKERS</label><strong>${fmt(e.workers)}</strong></div><div><label>INDUSTRY</label><strong>${esc(e.industry||'Unknown')}</strong></div><div><label>REPORTING DELAY</label><strong>${m.delay==null?'Not established':m.range?m.range.join(' to ')+' days':m.delay+' days'}</strong></div><div><label>DATE PRECISION</label><strong>Calendar day</strong></div></div>${e.synthetic?'<div class="notice example">Fictional employer and event. No external evidence exists for this illustration.</div>':''}<div class="evidence-block"><h3>The event timeline</h3>${dl.sort((a,b)=>a[1].localeCompare(b[1])).map(([label,d])=>`<div class="timeline-item"><span>${displayDate(d)}</span><div><b>${label}</b></div></div>`).join('')}</div><div class="evidence-block"><h3>Original source</h3><p>${esc(e.sourceTitle||'Official state WARN record')}</p>${safeLink(e.sourceUrl,'Open agency source ↗')}<p>${esc(e.sourceDateSemantics||'Date semantics require review before visibility analysis.')}</p><p>Record ID: ${esc(e.id)}${e.sourceRow?` · source row ${esc(e.sourceRow)}`:''}</p></div><div class="evidence-block"><h3>News matching & search audit</h3><p>${m.news?'Earliest verified match in the selected outlet set and search window.':'No verified in-window news match is recorded. This is not proof of absent reporting.'}</p>${m.news?safeLink(m.news.url,m.news.title||'Open publisher evidence ↗'):''}<p>Search window: ${e.searchStart?displayDate(e.searchStart)+' to '+displayDate(e.searchEnd):'Not completed'}<br>Review: ${e.reviewed?'Marked reviewed':'Pending'}<br>QCI eligibility: ${m.eligible?'Eligible for selected baseline':'Excluded: baseline or complete review unavailable'}</p>${e.matchingRationale?`<p>${esc(e.matchingRationale)}</p>`:''}</div><div class="evidence-block"><h3>Location & counting notes</h3><p>${esc(e.coordinatePrecision||'Approximate source location; coordinates may be unavailable.')}</p><p>Source rows may represent amendments or separate sites. Counts describe planned reductions, not verified job losses.</p></div>`;$('#evidence').showModal();$('#evidence').scrollTop=0}
function safeLink(url,label){try{if(new URL(url).protocol==='https:')return `<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)}</a>`}catch{}return '<span>No external source link for this illustration.</span>'}
function navigate(page){state.page=page;state.tablePage=0;history.replaceState(null,'','#'+page);render();window.scrollTo({top:0,behavior:'smooth'})}
function changeMode(){state.mode=$('#dataset').value;state.tablePage=0;$('#from').value='';$('#to').value='';$('#company').value='';refreshIndustries();render()}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Downloaded '+name)}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function exportCsv(){const keys=['id','company','state','city','industry','workers','noticeDate','receivedDate','processedDate','listedPostedDate','postedDate','effectiveDate','sourceUrl','reviewed','searchStart','searchEnd','searchCompleteNational','searchCompleteRegional','mode','analysisBaseline','outletSet','delayDays','delayRangeMin','delayRangeMax','coverageStatus','qciEligible'];const csv=[keys,...filtered().map(e=>{const m=measure(e,state.baseline,state.outlet);return keys.map(k=>({mode:state.mode,analysisBaseline:state.baseline,outletSet:state.outlet,delayDays:m.delay,delayRangeMin:m.range?.[0],delayRangeMax:m.range?.[1],coverageStatus:m.status,qciEligible:m.eligible}[k]??e[k]??''))})].map(row=>row.map(v=>{let s=String(v);if(/^[=+@\t\r]/.test(s)||(/^[-]/.test(s)&&!/^[-]\d+(\.\d+)?$/.test(s)))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(',')).join('\r\n');download(csv,'quiet-cuts-'+state.mode+'.csv','text/csv;charset=utf-8')}
async function importData(ev){try{const f=ev.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('File exceeds the 10 MB import limit.');imported=validateImport(JSON.parse(await f.text()));if(!$('#dataset option[value="imported"]'))$('#dataset').add(new Option('Imported reviewed records','imported'));$('#dataset').value='imported';changeMode();toast('Imported '+imported.length+' records for this session.')}catch(e){$('#import-error').textContent=e.message}}
function downloadSchema(){download(JSON.stringify({instructions:'Replace sample values with reviewed evidence. sourceUrl is required. postedDate means verified original public posting only; use listedPostedDate for uncertain postings. Set reviewed and completion flags true only after documented full-window searches. National outlets: Reuters, AP, NYT, WSJ, CNBC, CNN, BBC. Freeze a regional list before search. Null news + complete flags means no match found; missing review means incomplete. Never use GDELT observation time as publication time.',events:[{id:'replace-with-source-id',company:'Replace with employer',state:'CA',city:'',industry:'Unknown',workers:0,sourceUrl:'https://edd.ca.gov/en/jobs_and_training/layoff_services_warn/',sourceTitle:'Replace with precise source and row',sourceDateSemantics:'Describe date evidence',postedDate:null,receivedDate:null,noticeDate:null,effectiveDate:null,firstSeenDate:null,lastAbsentDate:null,lat:null,lon:null,reviewed:false,searchStart:null,searchEnd:null,searchCompleteNational:false,searchCompleteRegional:false,newsNational:null,newsRegional:null,matchingRationale:'News objects require date, url, title, verified:true. Include location/timing/worker count evidence.'}]},null,2),'quiet-cuts-import-template.json','application/json')}
document.querySelectorAll('nav [data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();navigate('overview')};$('#dataset').onchange=changeMode;for(const s of ['#state','#industry','#quality','#from','#to'])$(s).onchange=()=>{state.tablePage=0;render()};let debounce;$('#company').oninput=()=>{clearTimeout(debounce);debounce=setTimeout(()=>{state.tablePage=0;render()},220)};$('#reset').onclick=()=>{for(const s of ['#state','#industry','#company','#quality','#from','#to'])$(s).value='';state.tablePage=0;render()};$('#export').onclick=exportCsv;$('#close-dialog').onclick=()=>$('#evidence').close();$('#evidence').onclick=e=>{if(e.target===$('#evidence')&&e.clientX<$('#evidence').getBoundingClientRect().left)$('#evidence').close()};
try{const r=await fetch('data/events.json');if(!r.ok)throw Error('Source snapshot unavailable');const raw=await r.json();official=(Array.isArray(raw)?raw:raw.events).map(e=>({...e,industry:e.industry||'Unknown'}));metadata=raw.metadata||{};refreshIndustries();const page=location.hash.slice(1);if(['overview','latency','employers','method'].includes(page))state.page=page;await render()}catch(e){$('#view').innerHTML=`<div class="fatal">Unable to load the official snapshot: ${esc(e.message)}. You can still select the illustrative study above.</div>`;$('#mode-note').textContent='SOURCE SNAPSHOT COULD NOT LOAD';}
